import{t as e}from"./jsx-runtime-lw2jiZar.js";import{B as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,b as u,g as d,j as f,k as p,p as m,w as h,x as g}from"./shared-DhavWP79.js";import{t as _}from"./wrench-BJLceorR.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=`/platform/assets/query-filter-sort-limit-B9Mrqigb.svg`,b=e();function x({module:e}){return(0,b.jsxs)(a,{children:[(0,b.jsx)(i,{chip:e??`Месяц 3 · Блок 10 · Первый FastAPI`,title:`55. Query-параметры: фильтрация, сортировка и границы`,intro:`GET /tasks уже показывает реальные данные. Теперь научим тот же адрес отдавать удобную выборку, не меняя задачи в Planner.`,tags:[{icon:(0,b.jsx)(t,{size:14}),label:`чтение коллекции`},{icon:(0,b.jsx)(_,{size:14}),label:`filter · sort · limit`}]}),(0,b.jsx)(p,{variant:`connected`,items:[{title:`Прежняя опора`,description:`В прошлом занятии path выбирал одну задачу, а GET /tasks возвращал коллекцию.`},{title:`Новый вопрос`,description:`Как запросить подходящий вид коллекции, не меняя сами задачи?`},{title:`Результат`,description:`Добавим query-фильтр, сортировку и limit поверх данных того же Planner.`}]}),(0,b.jsxs)(s,{number:`01`,title:`Path выбирает объект, query настраивает список`,children:[(0,b.jsx)(o,{children:`В прошлом занятии GET /tasks/{task_id} выбирал одну задачу по id. Сам GET /tasks возвращает коллекцию. Query-параметры позволяют уточнить, какой вид этой коллекции нужен клиенту.`}),(0,b.jsx)(`p`,{children:`Сравним адреса. /tasks/7 указывает на одну запись. /tasks?is_done=false остаётся адресом списка, но просит показать только невыполненные задачи. Отдельный маршрут для каждой комбинации условий не нужен.`}),(0,b.jsx)(v,{caption:`Настройки после вопросительного знака`,code:`GET /tasks?is_done=false&sort_desc=true`}),(0,b.jsx)(`p`,{children:`После ? записываются пары «имя=значение», а несколько пар разделяются символом &. Их порядок в URL не задаёт порядок работы сервера. Адрес limit=10&is_done=false передаёт те же условия.`}),(0,b.jsx)(m,{prompt:`Сопоставим адрес с тем, что он выбирает.`,leftTitle:`Адрес`,rightTitle:`Результат`,pairs:[{left:`GET /tasks`,right:`Коллекция, по умолчанию не больше 10 задач`},{left:`GET /tasks/7`,right:`Одна задача с id 7`},{left:`GET /tasks?is_done=false`,right:`Открытые задачи в пределах limit`}],explanation:`Число в path обозначает конкретный ресурс. Query добавляет условия к чтению коллекции.`}),(0,b.jsx)(`p`,{children:`Фильтр, сортировка и limit меняют только ответ текущего GET. Это не команды удалить записи, переставить задачи в файле или сохранить новый порядок.`})]}),(0,b.jsxs)(s,{number:`02`,title:`У фильтра три состояния`,children:[(0,b.jsx)(o,{children:`У параметра is_done есть важное отличие от обычного переключателя. Кроме true и false есть отсутствие условия.`}),(0,b.jsx)(p,{items:[{title:`Параметр не передан`,description:`FastAPI передаёт None. Покажем задачи обоих статусов.`},{title:`is_done=true`,description:`Значение True. Оставим завершённые задачи.`},{title:`is_done=false`,description:`Значение False. Оставим открытые задачи.`}]}),(0,b.jsx)(`p`,{children:`Запись bool | None означает, что переменная принимает True, False или None. Объединение типов через | поддерживается в Python 3.10 и новее. None здесь не четвёртый статус задачи: это отсутствие условия фильтра. Для Planner эти три состояния соответствуют всем задачам, завершённым и открытым.`}),(0,b.jsx)(`p`,{children:`В URL значения выглядят как текст. FastAPI преобразует true и false в Python bool. Если параметр не указан, значение по умолчанию None. Значит, условие в сервисе должно проверять именно наличие значения.`}),(0,b.jsx)(`p`,{children:`Посмотрим на тот же принцип отдельно от Planner. В каталоге товаров None означает, что мы не отбираем товары по признаку скидки, а False означает явный запрос товаров без скидки:`}),(0,b.jsx)(v,{caption:`Независимый пример: фильтр каталога`,code:`if has_discount is not None:
    products = [
        product for product in products
        if product.has_discount == has_discount
    ]`}),(0,b.jsx)(d,{prompt:`Как проверить передачу необязательного признака скидки, не потеряв False?`,before:`if has_discount `,after:` None:
    # применить фильтр`,options:[`==`,`is not`,`or`],answer:`is not`,explanation:`Проверка на None отличает отсутствие параметра от явного False. Поэтому явный запрос товаров без скидки не пропускается.`}),(0,b.jsx)(n,{code:`if has_discount:
    products = [p for p in products if p.has_discount == has_discount]`,question:`Что произойдёт при запросе ?has_discount=false?`,options:[`False пропустит условие, и вернётся весь каталог`,`Python превратит False в None`,`Сервис вернёт 404`],correctIndex:0,explanation:`Обычная проверка truthy/falsy смешивает False с отсутствием значения. Для необязательного фильтра проверяют is not None.`,fix:`Заменим проверку значения на проверку has_discount is not None, чтобы False тоже запускало фильтр.`}),(0,b.jsx)(`p`,{children:`Если правильно заданный фильтр не нашёл совпадений, список пуст. Это успешное чтение коллекции, а не ошибка отсутствующего ресурса. Для такого ответа подходит 200 и []. Код 404 нужен для запроса конкретной задачи, которой нет по указанному id.`})]}),(0,b.jsxs)(s,{number:`03`,title:`FastAPI разбирает и проверяет query до обработчика`,children:[(0,b.jsx)(o,{children:`Клиент отправляет текст, а код маршрута должен получить значения ожидаемых типов. FastAPI делает это на границе HTTP.`}),(0,b.jsx)(`p`,{children:`Аннотация int просит целое число, bool просит логическое значение, а значение по умолчанию делает параметр необязательным. Например, ?limit=12 превращается в число 12. Если вместо числа пришло many, FastAPI останавливает запрос до вызова функции маршрута.`}),(0,b.jsx)(v,{caption:`Пример на отдельном каталоге книг`,code:`from fastapi import Query

@app.get("/books")
def list_books(
    newest: bool = False,
    limit: int = Query(default=10, ge=1, le=50),
):
    ...`}),(0,b.jsx)(`p`,{children:`Query задаёт правила для limit. ge=1 означает «не меньше 1», le=50 означает «не больше 50». Нижняя и верхняя границы входят в диапазон. Поэтому 1 и 50 допустимы, а 0 и 51 нет.`}),(0,b.jsx)(`p`,{children:`Для нашего API это выбранное правило: без limit клиент получает не больше 10 задач, а явно задать можно от 1 до 50. При неправильном типе или нарушении границы FastAPI возвращает 422. Проверка происходит до кода endpoint, поэтому сервис и файл не затронуты. Значение не округляют и не подменяют ближайшей границей.`}),(0,b.jsx)(h,{title:`Что произойдёт с query-параметром`,prompt:`Проследим этапы для GET /books?limit=12.`,pieces:[{id:`text`,code:`URL содержит текст limit=12`},{id:`parse`,code:`FastAPI преобразует значение в int и проверяет Query`},{id:`call`,code:`маршрут получает limit=12`}],correctOrder:[`text`,`parse`,`call`],explanation:`До вызова endpoint значение разбирается и проверяется. При ошибке преобразования или границы цепочка останавливается раньше.`,incorrectExplanation:`В URL limit сначала передаётся как текст. FastAPI преобразует его в int и проверяет ограничения до вызова endpoint.`}),(0,b.jsx)(u,{question:`Какой запрос нарушит правило limit от 1 до 50?`,options:[`?limit=1`,`?limit=50`,`?limit=51`],correctIndex:2,explanation:`Границы включены. Значение 51 превышает le=50, поэтому FastAPI вернёт 422 до вызова маршрута.`})]}),(0,b.jsxs)(s,{number:`04`,title:`Выборка проходит в заданном порядке`,children:[(0,b.jsx)(o,{children:`Когда вход уже проверен, сервис подготавливает ответ из актуальных задач Planner. Важно не только что сделать, но и в какой последовательности.`}),(0,b.jsx)(`p`,{children:`Сначала оставим подходящие задачи. Потом расположим их по id. И только в конце возьмём первые limit элементов. Например, в книжном магазине сначала выбирают книги нужного жанра, затем ставят их по году, а потом берут первые три. Если ограничить каталог до фильтра, подходящие книги могут не попасть в ответ.`}),(0,b.jsx)(`p`,{children:`Для сортировки объектов sorted нужен ключ сравнения. Функция key получает по одному объекту и возвращает значение, по которому его ставить в порядок. В примере с книгами ключом будет год издания:`}),(0,b.jsx)(v,{caption:`Независимый пример: сортировка книг по году`,code:`books = [
    {"title": "HTTP", "year": 2024},
    {"title": "Python", "year": 2021},
]

def publication_year(book):
    return book["year"]

older_first = sorted(books, key=publication_year)
newer_first = sorted(books, key=publication_year, reverse=True)`}),(0,b.jsx)(`p`,{children:`key=publication_year передаёт sorted функцию, которую он вызовет для каждой книги. Она возвращает год, а sorted сравнивает именно эти числа, не сами словари. Короткую функцию можно записать через lambda: key=lambda book: book["year"]. Запись lambda задаёт небольшую функцию без отдельного имени. По умолчанию reverse=False даёт возрастание; reverse=True меняет его на убывание. В Planner ключом становится task.id: sort_desc=False задаёт возрастание, sort_desc=True задаёт убывание.`}),(0,b.jsxs)(`figure`,{className:`lesson-infographic`,children:[(0,b.jsx)(`img`,{src:y,alt:`Каталог книг с годами 2024, 2019, 2021, 2023, 2018. Фильтр по году после 2020 оставляет три книги. Сортировка по возрастанию даёт 2021, 2023, 2024; limit=2 возвращает 2021 и 2023. Исходный каталог остаётся неизменным.`,width:1672,height:836,loading:`lazy`,decoding:`async`}),(0,b.jsx)(`figcaption`,{children:`На независимом примере виден порядок filter → sort → limit. Исходный каталог не перестраивается.`})]}),(0,b.jsx)(h,{title:`Порядок подготовки списка`,prompt:`Каталог должен оставить книги после 2020 года, расположить их по году от ранних к поздним и показать первые пять.`,pieces:[{id:`filter`,code:`оставить книги, выпущенные после 2020 года`},{id:`sort`,code:`упорядочить их по году издания`},{id:`limit`,code:`взять первые пять книг`},{id:`save`,code:`перезаписать исходный каталог в новом порядке`}],correctOrder:[`filter`,`sort`,`limit`],explanation:`Сначала выбираются подходящие книги, затем результат упорядочивается и ограничивается. Каталог остаётся прежним: GET готовит ответ, а не сохраняет новую коллекцию.`,incorrectExplanation:`Сначала отбираются книги нужного года, затем они сортируются по году издания и ограничиваются пятью. Перезапись каталога не входит в подготовку ответа.`}),(0,b.jsx)(n,{code:`books = books[:limit]
books = [book for book in books if book["year"] > 2020]
books = sorted(books, key=lambda book: book["year"])`,question:`Почему книга нужного года может не попасть в ответ?`,options:[`limit обрезал исходный каталог до отбора книг`,`sorted не умеет работать с годами`,`Фильтр всегда возвращает пустой список`],correctIndex:0,explanation:`Сначала срез оставил только начало исходного каталога. Подходящие книги за его границей не дошли до фильтра. Сначала отбираем и сортируем, потом ограничиваем.`,fix:`Перенесём срез после отбора и сортировки: filter → sort → limit.`})]}),(0,b.jsxs)(s,{number:`05`,title:`Сервис готовит данные, маршрут отвечает клиенту`,children:[(0,b.jsx)(o,{children:`Новый query не должен создавать второй источник задач или копировать бизнес-логику внутрь FastAPI.`}),(0,b.jsx)(p,{variant:`connected`,items:[{title:`FastAPI-маршрут`,description:`Принимает проверенные query и передаёт их сервису.`},{title:`PlannerService`,description:`Берёт актуальный список через уже существующий list_tasks и готовит выборку.`},{title:`HTTP-ответ`,description:`Показывает выбранные задачи в уже принятой проекции: id, title, priority, is_done.`}]}),(0,b.jsx)(`p`,{children:`В записи int | None переменная принимает целое число или None. Для сервиса limit=None означает, что выборка не обрезается. HTTP отдельно задаёт default 10. Так прежний list_tasks для CLI остаётся полным, а ограничение веб-ответа не переносится во всё приложение.`}),(0,b.jsx)(`p`,{children:`Для сортировки используем новый список, который возвращает sorted, а не метод sort на исходном списке. Сами Task при этом не нужно копировать, если маршрут только читает их поля и не меняет объекты. Срез тоже формирует новый список. Ни одна из этих операций не вызывает сохранение.`}),(0,b.jsx)(l,{question:`Где разместить выборку для GET /tasks?`,left:{title:`Новая операция PlannerService`,code:`select_tasks → list_tasks → filter → sort → limit`,note:`Сервис использует уже настроенный источник и остаётся общим для приложения.`},right:{title:`Отдельный JSON в маршруте`,code:`open("data/tasks.json") → собственный разбор`,note:`Появляется второй путь чтения, который может разойтись с CLI и остальным API.`},preferred:`left`,explanation:`Новая выборка продолжает существующую сервисную границу и не обходит storage.`}),(0,b.jsx)(`p`,{children:`Выборка не меняет статистику. GET /stats по-прежнему считает весь Planner, а не только показанные клиенту задачи. Поле tags остаётся внутри доменной Task и файла, но в публичный ответ автоматически не попадает.`}),(0,b.jsx)(c,{statement:`Если GET /tasks вернул две записи после limit=2, GET /stats тоже должен считать только эти две.`,isTrue:!1,explanation:`limit относится к одному ответу списка. Статистика и хранилище по-прежнему охватывают все задачи.`}),(0,b.jsx)(g,{question:`Почему CLI должен продолжать вызывать list_tasks, а не select_tasks с limit=10?`,answer:(0,b.jsx)(`p`,{children:`Десять это HTTP-дефолт, а не новое ограничение всего Planner. CLI сохраняет прежнее полное чтение.`})})]}),(0,b.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,b.jsx)(o,{children:`Мы расширим тот же Planner API: существующий список станет настраиваемым, но его источник и старые способы работы останутся прежними.`}),(0,b.jsx)(`p`,{children:`Сначала добавим select_tasks в PlannerService. Он будет читать через list_tasks, учитывать необязательный статус, сортировать по id и применять необязательный limit последним. Затем подключим параметры к уже существующему GET /tasks. FastAPI проверит типы и диапазон limit до вызова маршрута.`}),(0,b.jsx)(`p`,{children:`Сначала через CLI обеспечим больше десяти записей и найдём задачу с минимальным id. Для фильтра возьмём противоположный ей статус; если подходящих задач пока нет, добавим одну через CLI и обновим список. Запрос с этим фильтром, sort_desc=false и limit=1 должен вернуть задачу. Если выполнить сортировку, затем limit=1 и только после этого фильтр, останется задача с неподходящим статусом, а ответ станет пустым. Отдельно вызовем GET /tasks без query: ответ должен содержать первые десять задач по возрастанию id.`}),(0,b.jsx)(`p`,{children:`После подготовки данных, но до HTTP-запросов, сохраним полный CLI-список, stats и JSON. Это состояние станет точкой сравнения: добавления через CLI ожидаемы, а чтение через GET не должно менять подготовленные данные.`}),(0,b.jsx)(`p`,{children:`Для остальных запросов вычислим ожидаемый результат по полному CLI-списку: фильтр, сортировка по id, затем первые limit записей. Поэтому сравним HTTP не со всеми подходящими задачами, а с нужным префиксом. Проверим оба статуса и направления сортировки, limit=1 и limit=50, границы 422, а затем сверим полный список, одну задачу, статистику и JSON. Запросы меняют только состав ответа.`}),(0,b.jsxs)(r,{tone:`info`,children:[(0,b.jsx)(`strong`,{children:`За пределами практики.`}),` Не добавляем новые маршруты, хранилища, поля, произвольную сортировку или постраничную навигацию. GET /tasks остаётся тем же адресом.`]}),(0,b.jsx)(f,{text:`Добавим выборку в PlannerService, подключим проверенные query к существующему GET /tasks и подтвердим, что CLI, статистика и JSON не изменились.`})]})]})}export{x as Lesson55};